import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%A2%E3%83%B3%E3%83%86%E3%82%AB%E3%83%AB%E3%83%ADPolicyEvaluation.html","title":"モンテカルロPolicyEvaluation","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.36,"words":108},"filePathRelative":"モンテカルロPolicyEvaluation.md"}`),a={name:`モンテカルロPolicyEvaluation.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="モンテカルロpolicyevaluation" tabindex="-1"><a class="header-anchor" href="#モンテカルロpolicyevaluation"><span>モンテカルロPolicyEvaluation</span></a></h1><p><a href="./ModelFreePolicyEvaluation.html">ModelFreePolicyEvaluation</a>の一種。<a href="./強化学習.html">強化学習</a>。<a href="./TDLearning.html">TDLearning</a>、<a href="./CertaintyEquivalenceによるモデル推計.html">CertaintyEquivalenceによるモデル推計</a>。</p><p><a href="https://www.youtube.com/watch?v=jjq51TRNVvk&amp;list=PLoROMvodv4rN4wG6Nk6sNpTEbuOSosZdX&amp;index=3" target="_blank" rel="noopener noreferrer">Stanford CS234 Reinforcement Learning I Policy Evaluation I 2024 I Lecture 3 - YouTube</a></p><h2 id="mc-policy-evaluationとは" tabindex="-1"><a class="header-anchor" href="#mc-policy-evaluationとは"><span>MC Policy Evaluationとは</span></a></h2><p><img src="/RandomThoughts/assets/0001-WKYtiA1k.png" alt="imgs/CS234Lec3/0001.png"></p><p>エピソードをサンプリングしてVを更新、を繰り返す。 エピソード単位でないと使えない。</p><h2 id="アルゴリズムとfirstvisitとeveryvisitの違い" tabindex="-1"><a class="header-anchor" href="#アルゴリズムとfirstvisitとeveryvisitの違い"><span>アルゴリズムとFirstVisitとEveryVisitの違い</span></a></h2><p><img src="/RandomThoughts/assets/0002-BY_67dsA.png" alt="imgs/CS234Lec3/0002.png"></p><h3 id="インクリメンタル" tabindex="-1"><a class="header-anchor" href="#インクリメンタル"><span>インクリメンタル</span></a></h3><p>エピソードをサンプルして<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>G</mi><mrow><mi>i</mi><mo separator="true">,</mo><mi>t</mi></mrow></msub></mrow><annotation encoding="application/x-tex">G_{i, t}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>を定義する所までは変わらない。</p><p>各エピソードiのタイプステップtで、sに遭遇する都度Vを更新する。</p><p><img src="/RandomThoughts/assets/0003-Cyc7hJLn.png" alt="imgs/CS234Lec3/0003.png"></p><p>という事で1/Nを使ってもいいがそれにこだわらず、一般にラーニングレートのαならなんでも使って良い。</p><h2 id="_3つの手法の比較" tabindex="-1"><a class="header-anchor" href="#_3つの手法の比較"><span>3つの手法の比較</span></a></h2><p><img src="/RandomThoughts/assets/0006-CZNuFR87.png" alt="imgs/CS234Lec3/0006.png"></p><p>Consistentについては<a href="./ConsistentEstimator.html">ConsistentEstimator</a>を参照のこと。</p><h2 id="モンテカルロpolicy-evaluationの欠点" tabindex="-1"><a class="header-anchor" href="#モンテカルロpolicy-evaluationの欠点"><span>モンテカルロPolicy Evaluationの欠点</span></a></h2><p><img src="/RandomThoughts/assets/0007-CHbOmEDM.png" alt="imgs/CS234Lec3/0007.png"></p><p><a href="./バイアスとバリアンス.html">バイアスとバリアンス</a>も参照。<a href="./TDLearning.html">TDLearning</a>とも比較したい。</p><h2 id="policy-improvement" tabindex="-1"><a class="header-anchor" href="#policy-improvement"><span>Policy Improvement</span></a></h2><p><a href="./ModelFreePolicyImprovement.html">ModelFreePolicyImprovement</a>でε-greedyポリシーのMCのPolicy Improvementについて書いてある。</p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};